/// An automation routine, runnable via [`run_routine`].
///
/// Implementations hold their own configuration and mutable state; all
/// hardware access goes through the [`Rt`] passed to `run`.
pub trait Routine {
    /// Short identifier used in logs and events.
    fn name(&self) -> &str;

    /// Execute the routine to one of its endings.
    ///
    /// Return `Err(SpmError::ShutdownRequested)` freely from anywhere inside
    /// (it is what `rt.settle` and `rt.check_shutdown` produce); the harness
    /// converts it to `Ok(Outcome::StoppedByUser)`.
    fn run(&mut self, rt: &mut Rt) -> Result<Outcome, SpmError>;

    /// What the harness sets on the controller before `run`, and restores
    /// afterwards. The default sets a relative 50 nm Z home and leaves
    /// safe-tip alone; [`RunSetup::NONE`] touches nothing.
    fn run_setup(&self) -> RunSetup {
        RunSetup::default()
    }

    /// How the harness leaves the tip once `run` returns. The default
    /// withdraws without a coarse retract.
    fn exit_policy(&self) -> ExitPolicy {
        ExitPolicy::default()
    }
}

/// Bias voltage control. Errors if the controller lacks [`Capability::Bias`].
pub fn bias(&mut self) -> Result<Bias<'_, 'a>, SpmError> {
    self.require(Capability::Bias)?;
    Ok(Bias { rt: self })
}

pub(crate) fn require(controller: &dyn SpmController, cap: Capability) -> Result<(), SpmError> {
    if controller.capabilities().contains(&cap) {
        Ok(())
    } else {
        Err(SpmError::Unsupported(format!(
            "controller does not support the {cap:?} subsystem"
        )))
    }
}

/// Fire a bias pulse to an absolute signed voltage for `width_ms`, with
/// the z-controller held. The bias returns to its previous value after.
pub fn pulse(&mut self, voltage: f64, width_ms: u64) -> Result<()> {
    self.rt.exec(&BiasPulse {
        voltage,
        duration_ms: width_ms,
        ..Default::default()
    })?;
    Ok(())
}

/// Run `action` in `ctx`: check its capabilities, emit started, execute,
/// emit completed or failed. The params logged are the action's own fields,
/// and the depth is the context's, so every execution path writes the same
/// shape to the log whether a routine or a parent action started it.
pub fn run_action<A: Action + serde::Serialize>(
    ctx: &mut ActionContext,
    action: &A,
) -> Result<ActionOutput> {
    let name = action.name().to_string();
    let depth = ctx.depth;
    let params = serde_json::to_value(action).unwrap_or(serde_json::Value::Null);
    let start = Instant::now();
    ctx.events.emit(Event::action_started(&name, params, depth));
    let result = match check_capabilities(action, ctx.controller) {
        Ok(()) => action.execute(ctx),
        Err(e) => Err(e),
    };
    match result {
        Ok(output) => {
            ctx.events.emit(Event::action_completed(
                &name,
                &output,
                depth,
                start.elapsed(),
            ));
            Ok(output)
        }
        Err(e) => {
            ctx.events.emit(Event::action_failed(
                &name,
                &e.to_string(),
                depth,
                start.elapsed(),
            ));
            Err(e)
        }
    }
}

pub trait SpmController: Send {
    /// Report which capabilities this controller supports.
    fn capabilities(&self) -> HashSet<Capability>;

    // ...

    // -- Presets --

    /// Load a settings file into the controller. Requires
    /// [`Capability::Presets`]; the default reports it unsupported.
    ///
    /// The path is resolved on *this* machine and handed to the controller
    /// as an absolute path, so it has to be somewhere the controller's PC
    /// can read too. A load persists for the rest of the session and cannot
    /// be undone from here, which is what makes it a first-class operation:
    /// some module settings can only be set over TCP this way.
    fn load_settings(&mut self, _path: &Path) -> Result<()> {
        Err(SpmError::Unsupported(
            "this controller cannot load settings files".into(),
        ))
    }

    // ...

    // -- Bias --
    fn get_bias(&mut self) -> Result<f64>;
    fn set_bias(&mut self, voltage: f64) -> Result<()>;
    fn bias_pulse(
        &mut self,
        voltage: f64,
        width: Duration,
        z_hold: bool,
        absolute: bool,
    ) -> Result<()>;

fn bias_pulse(
    &mut self,
    voltage: f64,
    width: Duration,
    z_hold: bool,
    absolute: bool,
) -> Result<()> {
    let z_controller_hold = if z_hold {
        nanonis_rs::z_ctrl::ZControllerHold::Hold
    } else {
        nanonis_rs::z_ctrl::ZControllerHold::NoChange
    };
    let pulse_mode = if absolute {
        nanonis_rs::bias::PulseMode::Absolute
    } else {
        nanonis_rs::bias::PulseMode::Relative
    };
    let v = validate_f32(voltage, "pulse voltage")?;
    Ok(self.client.bias_pulse(
        true, // always wait for pulse to complete
        width.as_secs_f32(),
        v,
        z_controller_hold,
        pulse_mode,
    )?)
}

fn bias_pulse(
    &mut self,
    voltage: f64,
    _width: Duration,
    _z_hold: bool,
    _absolute: bool,
) -> Result<()> {
    self.enter("bias_pulse")?;
    self.obs.lock().pulses.push(voltage);
    Ok(())
}

impl Routine for TipPrep<'_> {
    fn name(&self) -> &str {
        "tip_prep"
    }

    fn run_setup(&self) -> RunSetup {
        RunSetup {
            // Spelled out rather than defaulted: the home step of every
            // calibrated approach is "back off 50 nm from wherever the tip
            // is". Absolute mode would make it "go to Z = +50 nm", surface
            // or not.
            z_home: Some(ZHome {
                mode: ZHomeMode::Relative,
                position_m: 50e-9,
            }),
            // Off for the run, restored on exit. A pulse is a current spike
            // by design, and safe-tip would retract on every one.
            safe_tip: Some(SafeTipSetup {
                threshold_a: self.config.tip_prep.safe_tip_threshold,
                disable: true,
            }),
        }
    }

    fn exit_policy(&self) -> ExitPolicy {
        ExitPolicy::Withdraw {
            retract_steps: self.config.tip_prep.timing.exit_retract_steps,
        }
    }

// Main loop: pulse -> settle -> reposition -> measure -> check sharp
// Matches V1 ordering: minimize time at pulsed position to avoid
// unintended tip changes from continued surface interaction.
let mut last_cycle = 0;
loop {
    // A config sent while running lands here, between cycles and
    // before the budgets are checked, so a lowered limit holds.
    self.take_reload(rt, last_cycle, &mut cycles);
    let Some(cycle) = cycles.next() else { break };
    last_cycle = cycle;
    let timing = self.config.tip_prep.timing.clone();

    // ...

    // Pulse with current voltage (determined by previous cycle's update)
    let pulse_voltage = self.pulse.signed_voltage();
    // ...
    rt.bias()?.pulse(pulse_voltage, timing.pulse_width_ms)?;
    rt.settle(timing.post_pulse_settle_ms)?;

    // Reposition immediately: get away from pulse site
    self.reposition(rt)?;

    // Measure at new position (after reposition)
    let mut freq_shift = self.read_stable(rt)?;
    let is_sharp = self.is_sharp(freq_shift);

    rt.emit(Event::typed(&CycleEvent {
        cycle,
        elapsed_secs: cycles.elapsed().as_secs_f64(),
        freq_shift,
        // The voltage that was fired, sign included. The pulse
        // state's `current_voltage` is a magnitude, and reporting
        // it hid every polarity switch from the GUI.
        pulse_voltage,
        is_sharp,
    }));

    if is_sharp {
        // ...
        match self.handle_stability(rt)? {
            None => return Ok(Outcome::Completed),
            // The check moved the tip, and the next pulse fires
            // where it left it.
            Some(fs) => freq_shift = fs,
        }
    }

    // Update voltage strategy for next cycle (uses post-reposition measurement)
    self.pulse
        .update_voltage(&self.config.pulse_method, Some(freq_shift));
}

Ok(cycles.outcome())

/// The Linear strategy's pulse magnitude for a frequency-shift reading.
///
/// A blunter tip reads further below zero, so the clamp's upper end is the one
/// nearest the sharp window. The gentlest pulse (`voltage_bounds.0`) falls
/// there and rises linearly to the hardest (`voltage_bounds.1`) at the clamp's
/// lower end; outside the clamp the hardest applies. Large pulses reshape the
/// apex unpredictably, so a tip close to sharp is only nudged.
pub fn linear_voltage(
    freq_shift: f64,
    voltage_bounds: (f64, f64),
    linear_clamp: (f64, f64),
) -> f64 {
    let (gentle, hard) = voltage_bounds;
    let (far, near) = linear_clamp;
    if !(far..=near).contains(&freq_shift) {
        return hard;
    }
    gentle + (near - freq_shift) / (near - far) * (hard - gentle)
}
